import z3

def check_counterexample(n, target_rad, target_tdn):
    s = z3.Solver()
    adj = [[z3.Bool(f"e_{i}_{j}") for j in range(n)] for i in range(n)]
    for i in range(n):
        s.add(z3.Not(adj[i][i]))
        for j in range(i+1, n):
            s.add(adj[i][j] == adj[j][i])
    in_S = [z3.Bool(f"in_S_{i}") for i in range(n)]
    s.add(z3.AtMost(*in_S, target_tdn))
    for v in range(n):
        s.add(z3.Or([z3.And(adj[v][u], in_S[u]) for u in range(n)]))
    dist = [[z3.Int(f"d_{i}_{j}") for j in range(n)] for i in range(n)]
    for i in range(n):
        for j in range(n):
            s.add(dist[i][j] >= 0, dist[i][j] <= n)
            if i == j:
                s.add(dist[i][j] == 0)
            else:
                s.add(z3.Implies(adj[i][j], dist[i][j] == 1))
    for i in range(n):
        for j in range(n):
            if i != j:
                for k in range(n):
                    s.add(z3.Implies(adj[k][j], dist[i][j] <= dist[i][k] + 1))
                s.add(z3.Or([z3.And(adj[k][j], dist[i][j] == dist[i][k] + 1) for k in range(n)]))
    for i in range(n):
        for j in range(n):
            s.add(dist[i][j] <= n - 1)
    for v in range(n):
        s.add(z3.Or([dist[v][w] >= target_rad for w in range(n)]))
    if s.check() == z3.sat:
        print(f"SAT for n={n}, rad>={target_rad}, tdn<={target_tdn}!")
        return True
    else:
        print(f"UNSAT for n={n}, rad>={target_rad}, tdn<={target_tdn}")
        return False

for n in range(6, 12):
    if check_counterexample(n, 4, 3):
        break
